"""Producer API additions to the ordinary authenticated Miniflux client."""
import json
import re
import threading
import time

import miniflux
import requests

from common.logger import logger


NAMESPACE = 'miniflux_ai'
DEFINITIONS = {
    'rating': 'Personal relevance generated by miniflux_ai: 1.0–10.0, exactly one decimal, using configured personal criteria',
    'summary': 'Article summary generated by miniflux_ai in the configured output language',
    'topics': 'Topic labels generated by miniflux_ai: sorted unique JSON array serialized as text; native publisher tags preferred',
}
OUTPUT_FIELDS = [f'{NAMESPACE}.{name}' for name in DEFINITIONS]
QUALIFIED_FIELD = re.compile(r'[a-z0-9_-]{1,64}\.[a-z0-9_-]{1,64}\Z')


class MetadataAPIError(RuntimeError):
    """Controlled diagnostics only: never retain HTTP bodies, values or headers."""
    def __init__(self, operation, status=None, *, entry_id=None, fields=(), category=None):
        self.operation = operation
        self.status_code = status
        self.entry_id = entry_id
        self.fields = tuple(fields)
        self.retryable = status is None or status == 429 or (status is not None and 500 <= status <= 599)
        self.category = category or ({400: 'validation_or_registration', 401: 'authentication',
                                     403: 'access', 404: 'entry_not_found'}.get(status, 'temporary' if self.retryable else 'unexpected_response'))
        if self.category == 'incompatible':
            self.retryable = False
        advice = {
            'incompatible': 'Deploy the metadata-enabled Miniflux fork before enabling metadata mode.',
            'validation_or_registration': 'Check field registration, selected input fields and producer configuration.',
            'unregistered_field': 'Registry changed; definitions will be registered again before the next attempt.',
            'authentication': 'Check the configured Miniflux credentials.',
            'access': 'Check the Miniflux user and entry access.',
            'entry_not_found': 'Entry was deleted or is inaccessible; enrichment is not complete.',
            'invalid_response': 'Expected the metadata fork API contract; check the Miniflux URL and version.',
        }.get(self.category, 'Saved work is retained; temporary failures use bounded backoff.')
        super().__init__(f'operation={operation} entry_id={entry_id} fields={",".join(fields)} '
                         f'http_status={status} retryable={self.retryable} category={self.category}. {advice}')


class Client(miniflux.Client):
    def __init__(self, *args, retries=2, **kwargs):
        super().__init__(*args, **kwargs)
        self.retries = retries
        self._registration_lock = threading.Lock()
        self._ready_until = 0
        self._ready_fields = ()
        self._readiness_error = None
        self._error_until = 0
        self._write_verified = False

    def _request(self, method, path, operation, *, expected=(200,), entry_id=None,
                 fields=(), capability=False, **kwargs):
        error = None
        for attempt in range(self.retries + 1):
            try:
                response = self._session.request(method, self._get_endpoint(path), timeout=self._timeout,
                                                 allow_redirects=False, **kwargs)
            except requests.RequestException:
                error = MetadataAPIError(operation, entry_id=entry_id, fields=fields, category='transport')
            else:
                status = response.status_code
                if status in expected:
                    if status == 204:
                        return None
                    try:
                        return response.json()
                    except ValueError:
                        raise MetadataAPIError(operation, status, entry_id=entry_id, fields=fields,
                                               category='invalid_response') from None
                category = 'incompatible' if capability and status in (404, 405, 501) else None
                if status == 400:
                    # Categorize the normal error shape, never echo arbitrary server text.
                    try:
                        message = response.json().get('error_message', '')
                    except (ValueError, AttributeError):
                        message = ''
                    if isinstance(message, str) and 'is not registered' in message:
                        category = 'unregistered_field'
                error = MetadataAPIError(operation, status, entry_id=entry_id, fields=fields, category=category)
            if not error.retryable or attempt == self.retries:
                self._ready_until = 0
                if operation in ('patch_metadata', 'verify_write') and error.category not in ('entry_not_found', 'unregistered_field'):
                    # Stop new generation while persistence is known unavailable.
                    # Already-running generation can still finish into the outbox.
                    self._readiness_error = error
                    self._error_until = time.monotonic() + 30
                raise error from None
            time.sleep(min(2 ** (attempt + 1), 30))

    def register_metadata(self, name, description):
        field = f'{NAMESPACE}.{name}'
        result = self._request('POST', '/meta/register', 'register', expected=(200, 201),
                               fields=(field,), capability=True,
                               json={'client_id': NAMESPACE, 'name': name, 'description': description})
        if not isinstance(result, dict) or result.get('qualified_name') != field:
            raise MetadataAPIError('register', 200, fields=(field,), category='invalid_response')
        return result

    def list_metadata(self, client_id=None):
        result = self._request('GET', '/meta', 'list_definitions', capability=True,
                               params={'client_id': client_id} if client_id else None)
        if not isinstance(result, list):
            raise MetadataAPIError('list_definitions', 200, category='invalid_response')
        return result

    def ensure_metadata(self, input_fields=(), *, force=False):
        """No disk/global registry cache: fresh clients and polling cycles re-register.

        Serialized readiness prevents a worker fan-out on startup. A short negative
        cache prevents incompatible instances from causing per-article probes.
        """
        fields = tuple(dict.fromkeys(OUTPUT_FIELDS + list(input_fields)))
        with self._registration_lock:
            now = time.monotonic()
            if not force and now < self._ready_until and fields == self._ready_fields:
                return
            if not force and now < self._error_until and fields == self._ready_fields:
                raise self._readiness_error
            self._ready_until = 0
            self._write_verified = False
            self._ready_fields = fields
            try:
                self.list_metadata(NAMESPACE)
                for name, description in DEFINITIONS.items():
                    self.register_metadata(name, description)
                # Named projection validates selected external definitions too.
                page = self.get_entries(limit=1, meta=list(fields))
                if not isinstance(page, dict) or not isinstance(page.get('entries'), list):
                    raise MetadataAPIError('verify_projection', 200, fields=fields, category='invalid_response')
                if page['entries']:
                    self._probe_write(page['entries'][0]['id'])
            except MetadataAPIError as exc:
                self._readiness_error = exc
                self._error_until = time.monotonic() + 30
                raise
            self._error_until = 0
            self._ready_until = time.monotonic() + 300

    def _probe_write(self, entry_id):
        # The server accepts an empty atomic merge: no assignment/content changes.
        self._request('PATCH', f'/entries/{entry_id}/meta/{NAMESPACE}', 'verify_write',
                      expected=(204,), entry_id=entry_id, json={}, capability=True)
        self._write_verified = True

    def verify_metadata_write(self, entry_id):
        with self._registration_lock:
            if not self._write_verified:
                self._probe_write(entry_id)

    def get_entry(self, entry_id, *, meta=None):
        params = {'meta': meta} if meta is not None else None
        result = self._request('GET', f'/entries/{entry_id}', 'get_entry', entry_id=entry_id,
                               fields=meta or (), params=params)
        if not isinstance(result, dict) or (meta and not isinstance(result.get('meta'), dict)):
            raise MetadataAPIError('get_entry', 200, entry_id=entry_id, fields=meta or (), category='invalid_response')
        return result

    def get_entries(self, **kwargs):
        fields = kwargs.get('meta') or ()
        result = self._request('GET', '/entries', 'discover_entries', fields=fields,
                               params=self._get_params(**kwargs))
        if (not isinstance(result, dict) or not isinstance(result.get('entries'), list)
                or not isinstance(result.get('total'), int)
                or any(not isinstance(entry, dict) or (fields and not isinstance(entry.get('meta'), dict))
                       for entry in result['entries'])):
            raise MetadataAPIError('discover_entries', 200, fields=fields, category='invalid_response')
        return result

    def patch_metadata(self, entry_id, values):
        fields = tuple(f'{NAMESPACE}.{name}' for name in values)
        if any(not isinstance(value, str) or '\x00' in value for value in values.values()):
            raise MetadataAPIError('patch_metadata', 400, entry_id=entry_id, fields=fields,
                                   category='validation_or_registration')
        try:
            body = json.dumps(values, ensure_ascii=False).encode('utf-8')
        except UnicodeEncodeError:
            raise MetadataAPIError('patch_metadata', 400, entry_id=entry_id, fields=fields,
                                   category='validation_or_registration') from None
        if len(body) > 4 << 20:
            raise MetadataAPIError('patch_metadata', 400, entry_id=entry_id, fields=fields,
                                   category='validation_or_registration')
        self._request('PATCH', f'/entries/{entry_id}/meta/{NAMESPACE}', 'patch_metadata', expected=(204,),
                      entry_id=entry_id, fields=fields, data=body, headers={'Content-Type': 'application/json'})
        logger.info('operation=patch_metadata entry_id=%s fields=%s http_status=204 fields_written=%d',
                    entry_id, ','.join(fields), len(values))


def create_client(config):
    return Client(config.miniflux_base_url, api_key=config.miniflux_api_key,
                  timeout=config.miniflux_timeout, retries=config.miniflux_retries)
